const x = $json.body,
  m = x?.meta,
  d = x?.data,
  p = x?.previous,
  companyId = "YOUR_COMPANY_ID";
if (!/^\d+$/.test(companyId)) throw Error("Configure company ID");
if (
  !m ||
  m.version !== "2.0" ||
  m.entity !== "deal" ||
  m.action !== "change" ||
  String(m.company_id) !== companyId ||
  !d ||
  !p ||
  typeof p !== "object"
)
  throw Error("Invalid event");
if (!Object.prototype.hasOwnProperty.call(p, "won_time") || p.won_time === d.won_time)
  return { json: { orgId: 1, process: false } };
if (!Object.prototype.hasOwnProperty.call(d, "won_time")) throw Error("Missing won time");
const orgId = Number(d.org_id);
if (!Number.isSafeInteger(orgId) || orgId <= 0) throw Error("Missing organization");
return { json: { orgId, process: true } };

function organization({ organization, countryMap }) {
  const name = organization?.name,
    raw = organization?.address;
  if (typeof name !== "string" || !name.trim() || name.trim().length > 256 || /[\r\n]/.test(name))
    throw Error("Organization name is required");
  if (raw != null && typeof raw !== "object") throw Error("Invalid organization address");
  const v = (k) => raw?.[k];
  let country = v("country");
  if (country != null && country !== "") {
    if (typeof country !== "string" || !country.trim()) throw Error("Invalid country");
    const codes = new Set(
        "AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW".split(
          " ",
        ),
      ),
      key = country.trim().replace(/\s+/g, " ").toLowerCase(),
      aliases = countryMap ?? {};
    if (typeof aliases !== "object" || Array.isArray(aliases))
      throw Error("Invalid country mapping");
    let matches = [];
    for (const [name, value] of Object.entries(aliases)) {
      if (typeof value !== "string" || !codes.has(value.toUpperCase()))
        throw Error("Invalid country mapping");
      if (name.trim().replace(/\s+/g, " ").toLowerCase() === key) matches.push(value.toUpperCase());
    }
    if (matches.length === 0) {
      const display = new Intl.DisplayNames(["en"], { type: "region" });
      for (const c of codes)
        if (c.toLowerCase() === key || display.of(c).replace(/\s+/g, " ").toLowerCase() === key)
          matches.push(c);
    }
    matches = [...new Set(matches)];
    if (matches.length !== 1) throw Error("Unknown or ambiguous country; configure a mapping");
    country = matches[0];
  }
  const address = {};
  for (const [key, value] of Object.entries({
    city: v("locality"),
    line1: [v("route"), v("street_number")].filter(Boolean).join(" "),
    state: v("admin_area_level_1"),
    country: country?.toUpperCase(),
    postal_code: v("postal_code"),
  }))
    if (value != null && value !== "") {
      if (typeof value !== "string") throw Error("Invalid address component");
      address[key] = value;
    }
  return {
    name: name.trim(),
    address,
    query: "name:'" + name.trim().replace(/\\/g, "\\\\").replace(/'/g, "\\'") + "'",
  };
}

const x = $json;
return {
  json: organization({
    organization: {
      name: x.Name,
      address: {
        locality: x["City/town/village/locality"],
        route: x["Street/road name"],
        street_number: x["House number"],
        admin_area_level_1: x["State/county"],
        country: x.Country,
        postal_code: x["ZIP/Postal code"],
      },
    },
    countryMap: {},
  }),
};

function search({ customers }) {
  if (!customers || !Array.isArray(customers.data) || typeof customers.has_more !== "boolean")
    throw Error("Invalid Stripe search response");
  if (customers.data.length === 0 && customers.has_more)
    throw Error("Inconsistent Stripe search page");
  return { create: customers.data.length === 0 };
}

return { json: search({ customers: $json }) };
